CREATE OR ALTER PROCEDURE [dbo].[uspInventoryTransaction_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @TransactionType NVARCHAR(MAX) = NULL
	, @WarehouseId UNIQUEIDENTIFIER = NULL
	, @StorageLocationId UNIQUEIDENTIFIER = NULL
	, @IngredientId UNIQUEIDENTIFIER = NULL
	, @ReferenceType NVARCHAR(MAX) = NULL
	, @ReferenceId UNIQUEIDENTIFIER = NULL
	, @MaterialLotId UNIQUEIDENTIFIER = NULL
	, @UnitId UNIQUEIDENTIFIER = NULL
	, @TransactionNumber NVARCHAR(MAX) = NULL
	, @TransactionDate DATETIME = NULL
	, @QuantityIn DECIMAL(18,4) = NULL
	, @QuantityOut DECIMAL(18,4) = NULL
	, @Reason NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[TransactionType]
			, t.[WarehouseId]
			, t.[StorageLocationId]
			, t.[IngredientId]
			, t.[ReferenceType]
			, t.[ReferenceId]
			, t.[Quantity]
			, t.[UnitCost]
			, t.[TransactionDate]
			, t.[Note]
			, t.[MaterialLotId]
			, t.[TransactionNumber]
			, t.[QuantityIn]
			, t.[QuantityOut]
			, t.[UnitId]
			, t.[Reason]
			, t.[CreatedDate]
		FROM [dbo].[InventoryTransaction] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[TransactionNumber] LIKE CONCAT('%', @SearchText, '%'))
			AND (ISNULL(@TransactionType, '') = '' OR t.[TransactionType] = @TransactionType)
			AND (@WarehouseId IS NULL OR t.[WarehouseId] = @WarehouseId)
			AND (@StorageLocationId IS NULL OR t.[StorageLocationId] = @StorageLocationId)
			AND (@IngredientId IS NULL OR t.[IngredientId] = @IngredientId)
			AND (ISNULL(@ReferenceType, '') = '' OR t.[ReferenceType] = @ReferenceType)
			AND (@ReferenceId IS NULL OR t.[ReferenceId] = @ReferenceId)
			AND (@MaterialLotId IS NULL OR t.[MaterialLotId] = @MaterialLotId)
			AND (@UnitId IS NULL OR t.[UnitId] = @UnitId)
			AND (ISNULL(@TransactionNumber, '') = '' OR t.[TransactionNumber] LIKE CONCAT('%', @TransactionNumber, '%'))
			AND (@TransactionDate IS NULL OR t.[TransactionDate] = @TransactionDate)
			AND (@QuantityIn IS NULL OR t.[QuantityIn] = @QuantityIn)
			AND (@QuantityOut IS NULL OR t.[QuantityOut] = @QuantityOut)
			AND (ISNULL(@Reason, '') = '' OR t.[Reason] LIKE CONCAT('%', @Reason, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'transactionType' THEN r.[TransactionType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'transactionType' THEN r.[TransactionType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'warehouseId' THEN r.[WarehouseId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'warehouseId' THEN r.[WarehouseId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'storageLocationId' THEN r.[StorageLocationId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'storageLocationId' THEN r.[StorageLocationId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'ingredientId' THEN r.[IngredientId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'ingredientId' THEN r.[IngredientId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'referenceType' THEN r.[ReferenceType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'referenceType' THEN r.[ReferenceType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'referenceId' THEN r.[ReferenceId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'referenceId' THEN r.[ReferenceId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'quantity' THEN r.[Quantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'quantity' THEN r.[Quantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'unitCost' THEN r.[UnitCost] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'unitCost' THEN r.[UnitCost] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'transactionDate' THEN r.[TransactionDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'transactionDate' THEN r.[TransactionDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'materialLotId' THEN r.[MaterialLotId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'materialLotId' THEN r.[MaterialLotId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'transactionNumber' THEN r.[TransactionNumber] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'transactionNumber' THEN r.[TransactionNumber] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'quantityIn' THEN r.[QuantityIn] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'quantityIn' THEN r.[QuantityIn] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'quantityOut' THEN r.[QuantityOut] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'quantityOut' THEN r.[QuantityOut] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'unitId' THEN r.[UnitId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'unitId' THEN r.[UnitId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'reason' THEN r.[Reason] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'reason' THEN r.[Reason] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
